"""ops_trace.py  --  records what the agent does as a TRACE.   >>> YOU DO NOT EDIT THIS FILE <<<

A TRACE = one run of the agent, from the question to the final answer.
A SPAN  = one step inside it: a model call ("llm"), a tool call ("tool") or the whole run ("agent").
Every span stores: when it started, how long it took, what went in, what came out, tokens, cost, error.

Three places the same run can be seen (tab 1 shows all three):
  1. THIS APP        every trace is saved in submission/traces.jsonl and drawn in the app            always on
  2. LANGFUSE        open-source tracing tool; spans are sent live when you enter your team keys       optional
  3. AWS CLOUDWATCH  Bedrock itself logs every model call (tokens, who called) when the trainer
                     switched on "model invocation logging". No code in this file: it is AWS's side.
"""
import json
import os
import time
import uuid
from contextlib import contextmanager
from datetime import datetime
from pathlib import Path

HERE = Path(__file__).resolve().parent
STORE = HERE / "submission" / "traces.jsonl"


def clip(x, n=700):
    t = x if isinstance(x, str) else json.dumps(x, default=str, ensure_ascii=False)
    return t if len(t) <= n else t[:n] + f"... [{len(t) - n} more characters]"


# ------------------------------------------------------------------------------------------------ Langfuse (optional)
def langfuse_client():
    """Return a Langfuse client when the team keys are set, else None. Never raises."""
    if not (os.getenv("LANGFUSE_PUBLIC_KEY") and os.getenv("LANGFUSE_SECRET_KEY")):
        return None
    try:
        from langfuse import Langfuse
        host = os.getenv("LANGFUSE_HOST") or os.getenv("LANGFUSE_BASE_URL") or "https://cloud.langfuse.com"
        return Langfuse(public_key=os.environ["LANGFUSE_PUBLIC_KEY"], secret_key=os.environ["LANGFUSE_SECRET_KEY"], host=host)
    except Exception:                                                   # noqa: BLE001
        return None


def langfuse_check(lf):
    """(ok, message) for the sidebar button."""
    if lf is None:
        return False, "No Langfuse keys yet (the lab still works without them)."
    try:
        return (True, "Connected to Langfuse. New runs are sent live.") if lf.auth_check() else (False, "Langfuse said the keys are wrong.")
    except Exception as e:                                              # noqa: BLE001
        return False, f"Could not reach Langfuse: {type(e).__name__}. Check the host and your network."


# ------------------------------------------------------------------------------------------------ the tracer
class Tracer:
    """Use:  tr = Tracer('ticket question', model='...', provider='bedrock', lf=client_or_None)
             with tr.run(question):            # the whole run
                 with tr.span('llm', 'model call 1', input=...) as s:  s['output'] = ...; s['tokens_in'] = ...
    """

    def __init__(self, name, model="", provider="", price_key="", lf=None, tags=None):
        self.trace = {"trace_id": uuid.uuid4().hex[:12], "name": name, "model": model, "provider": provider, "price_key": price_key,
                      "started": datetime.now().isoformat(timespec="seconds"), "spans": [], "tags": tags or {},
                      "answer": "", "status": "ok", "langfuse_id": "", "langfuse_url": ""}
        self.lf = lf
        self._t0 = time.perf_counter()
        self._stack = []

    # ---- whole run
    @contextmanager
    def run(self, question):
        self.trace["question"] = question
        self._t0 = time.perf_counter()
        cm = None
        try:
            if self.lf:
                cm = self.lf.start_as_current_observation(name=self.trace["name"], as_type="agent", input=question,
                                                           metadata={"model": self.trace["model"], **self.trace["tags"]})
                self._root = cm.__enter__()
                self.trace["langfuse_id"] = getattr(self._root, "trace_id", "") or ""
        except Exception:                                               # noqa: BLE001
            cm = None
        try:
            yield self
        except Exception as e:                                          # noqa: BLE001
            self.trace["status"] = "error"
            self.trace["error"] = f"{type(e).__name__}: {e}"
            raise
        finally:
            self._finish(cm)

    def _finish(self, cm):
        t = self.trace
        t["ms"] = round((time.perf_counter() - self._t0) * 1000)
        t["tokens_in"] = sum(s.get("tokens_in", 0) for s in t["spans"])
        t["tokens_out"] = sum(s.get("tokens_out", 0) for s in t["spans"])
        t["cost_usd"] = round(sum(s.get("cost_usd", 0) for s in t["spans"]), 8)
        t["llm_calls"] = sum(1 for s in t["spans"] if s["kind"] == "llm")
        t["tool_calls"] = sum(1 for s in t["spans"] if s["kind"] == "tool")
        if cm is not None:
            try:
                self._root.update(output=t.get("answer", ""), level="ERROR" if t["status"] == "error" else "DEFAULT")
                cm.__exit__(None, None, None)
                self.lf.flush()
                t["langfuse_url"] = self.lf.get_trace_url(trace_id=t["langfuse_id"]) or ""
            except Exception:                                           # noqa: BLE001
                pass

    # ---- one step
    @contextmanager
    def span(self, kind, name, input=None, parent=None):
        s = {"id": len(self.trace["spans"]) + 1, "kind": kind, "name": name, "input": clip(input) if input is not None else "",
             "output": "", "start_ms": round((time.perf_counter() - self._t0) * 1000), "ms": 0, "tokens_in": 0, "tokens_out": 0,
             "cost_usd": 0.0, "error": "", "model": self.trace["model"] if kind == "llm" else ""}
        self.trace["spans"].append(s)
        t0 = time.perf_counter()
        cm = obs = None
        try:
            if self.lf:
                cm = self.lf.start_as_current_observation(name=name, as_type="generation" if kind == "llm" else ("retriever" if name == "search_kb" else "tool"), input=s["input"],
                                                           model=self.trace["model"] if kind == "llm" else None)
                obs = cm.__enter__()
        except Exception:                                               # noqa: BLE001
            cm = obs = None
        try:
            yield s
        except Exception as e:                                          # noqa: BLE001
            s["error"] = f"{type(e).__name__}: {e}"
            raise
        finally:
            s["ms"] = round((time.perf_counter() - t0) * 1000)
            s["output"] = clip(s["output"]) if s["output"] != "" else ""
            if cm is not None:
                try:
                    kw = {"output": s["output"], "level": "ERROR" if s["error"] else "DEFAULT"}
                    if kind == "llm":
                        kw["usage_details"] = {"input": s["tokens_in"], "output": s["tokens_out"]}
                        kw["cost_details"] = {"total": s["cost_usd"]}
                    obs.update(**kw)
                    cm.__exit__(None, None, None)
                except Exception:                                       # noqa: BLE001
                    pass


# ------------------------------------------------------------------------------------------------ saving
def save(trace):
    STORE.parent.mkdir(parents=True, exist_ok=True)
    with open(STORE, "a", encoding="utf-8") as f:
        f.write(json.dumps(trace, ensure_ascii=False, default=str) + "\n")


def load_all(limit=200):
    if not STORE.is_file():
        return []
    rows = []
    for line in STORE.read_text(encoding="utf-8").splitlines()[-limit:]:
        try:
            rows.append(json.loads(line))
        except Exception:                                               # noqa: BLE001
            pass
    return rows


def span_rows(trace):
    """Flat rows for a table."""
    return [{"#": s["id"], "kind": s["kind"], "step": s["name"], "start ms": s["start_ms"], "took ms": s["ms"],
             "tokens in": s["tokens_in"], "tokens out": s["tokens_out"], "cost $": round(s["cost_usd"], 7), "error": s["error"],
             "input": s["input"][:110], "output": s["output"][:110]} for s in trace["spans"]]
